function s(v){return String(v==null?'':v).trim();}
function nz(x){return s(x).toLowerCase().replace(/[^a-z0-9]/g,'');}
function colL(i){let n=i+1,t='';while(n>0){const m=(n-1)%26;t=String.fromCharCode(65+m)+t;n=Math.floor((n-1)/26);}return t;}
const vr=$('GET pilot').first().json.valueRanges||[];
const inv=(vr[0]||{}).values||[], crit=(vr[1]||{}).values||[], pipe=(vr[2]||{}).values||[];
if(inv.length<150||crit.length<200||pipe.length<5000){throw new Error('ABORT short read');}
if(inv.some(function(r){return /parnika@phy-sis\.com/i.test(s(r[2]));})){throw new Error('ABORT: Parnika already on INVESTORS');}
const data=[];const put=(range,v)=>data.push({range:range,values:[[v]]});
const TODAY=new Date(Date.now()+330*60000).toISOString().slice(0,10);
const pIdx=[];inv.forEach(function(r,i){if(i>0&&nz(r[0]).indexOf('physis')===0){pIdx.push(i);}});
if(pIdx.length!==1){throw new Error('ABORT: expected 1 Physis INVESTORS row, found '+pIdx.length);}
const pRow=pIdx[0]+1; const oldName=s(inv[pIdx[0]][0]); const oldContact=s(inv[pIdx[0]][1]); const oldEmail=s(inv[pIdx[0]][2]).toLowerCase();
const CONSUMER='D2C_BEAUTY_PERSONAL_CARE, D2C_HEALTH_WELLNESS, D2C_FASHION_JEWELLERY, D2C_HOME_LIFESTYLE, FNB_PACKAGED_FOOD, FNB_BEVERAGE, FNB_FOODSERVICE, ALCOHOL, MEAT_SEAFOOD, CONSUMER_TECH_APP, CONSUMER_SERVICES, QUICK_HYPERLOCAL_COMMERCE, PET, TRAVEL_HOSPITALITY';
const STAGE='Pre-Series A, Series A, Series B';
put('INVESTORS!A'+pRow,'Physis Capital - Parnika');put('INVESTORS!B'+pRow,'Parnika');put('INVESTORS!C'+pRow,'parnika@phy-sis.com');put('INVESTORS!D'+pRow,'');
put('INVESTORS!E'+pRow,'Sector agnostic incl. SaaS (no ARR criteria) - consumer handled on the Consumer row');put('INVESTORS!F'+pRow,STAGE);put('INVESTORS!G'+pRow,'INR 10 Cr (US$50M fund)');
const gRow=inv.length+1;
data.push({range:'INVESTORS!A'+gRow+':J'+gRow,values:[['Physis Capital - Parnika (Consumer)','Parnika','parnika@phy-sis.com','','Consumer (ARR at least INR 15 Cr)',STAGE,'INR 10 Cr (US$50M fund)','','','']]});
const ch=(crit[0]||[]).map(s);const CX={};ch.forEach((k,i)=>CX[k]=i);
let cr=-1;for(let i=1;i<crit.length;i++){if(nz((crit[i]||[])[CX.investor]).indexOf('physis')===0){cr=i+1;}}
if(cr<0){throw new Error('ABORT physis criteria row missing');}
function cset(col,v){put('INVESTOR_CRITERIA!'+colL(CX[col])+cr,v);}
const A={investor:'Physis Capital - Parnika',status:'ACTIVE',confirmed:'AUTO',review_reason:'',sector_mode:'AGNOSTIC',sectors_in:'',sectors_excluded:CONSUMER,models_in:'ANY',models_excluded:'',stage_min:'PRE_SERIES_A',stage_max:'SERIES_B',cheque_min_cr:'10',arr_min_cr:'',arr_min_strict:'N',revenue_required:'N',geography_scope:'INDIA',thesis_summary:'User 17 Sep: Jatin has left; Parnika (parnika@phy-sis.com). US$50M fund, Pre-Series A to Series B, sector agnostic, INR 10 Cr cheque. SaaS has no ARR criteria; consumer needs ARR >= INR 15 Cr (separate Consumer row, same inbox).',confidence:'HIGH',rule_notes:'user 17 Sep thesis; consumer sectors moved to the Consumer row'};
Object.keys(A).forEach(function(k){if(CX[k]!==undefined){cset(k,A[k]);}});
const B=Object.assign({},A,{investor:'Physis Capital - Parnika (Consumer)',sector_mode:'LIST',sectors_in:CONSUMER,sectors_excluded:'',arr_min_cr:'15',rule_notes:'user 17 Sep: consumer startups need ARR >= INR 15 Cr'});
const base=(crit[cr-1]||[]).slice();while(base.length<ch.length){base.push('');}
const bVals=ch.map(function(k,i){if(k==='sheet_row'){return String(gRow);} return B[k]!==undefined?B[k]:s(base[i]);});
const cNew=crit.length+1;data.push({range:'INVESTOR_CRITERIA!A'+cNew+':'+colL(ch.length-1)+cNew,values:[bVals]});
// PIPELINE: rows to the old contact
const h=(pipe[0]||[]).map(s);const X={};h.forEach((k,i)=>X[k]=i);
let stopped=0,dropped=0,skipped=0;const touched=[];
for(let i=1;i<pipe.length;i++){const r=pipe[i]||[];const rn=i+1;const g=k=>s(r[X[k]]);
  const hit=nz(g('investor')).indexOf('physis')===0||(oldEmail&&g('email').toLowerCase().indexOf(oldEmail)>=0);
  if(!hit){continue;} if(g('investor_response')){skipped++;continue;}
  const sent=/^yes$/i.test(g('deal_shared'));const na=g('next_action');const notes=g('notes');const note='Jatin left Physis Capital (user '+TODAY+'); Parnika now covers it';
  if(sent){put('PIPELINE!'+colL(X.pause)+rn,'Yes');put('PIPELINE!'+colL(X.notes)+rn,(notes?notes+' | ':'')+note+' - follow-ups stopped');stopped++;touched.push(g('deal_id')+' sent '+g('startup'));}
  else{if(/^DROPPED - replaced by/.test(na)){skipped++;continue;} put('PIPELINE!'+colL(X.pause)+rn,'Yes');put('PIPELINE!'+colL(X.next_action)+rn,'DROPPED - contact left firm (Jatin)');put('PIPELINE!'+colL(X.notes)+rn,(notes?notes+' | ':'')+note+' - engine re-matches for Parnika');dropped++;touched.push(g('deal_id')+' queued '+g('startup')+' was '+na.slice(0,20));}
}
if(stopped+dropped>80){throw new Error('ABORT unexpected Physis row count '+(stopped+dropped));}
return [{json:{data:data,summary:{old:{name:oldName,contact:oldContact,email:oldEmail},investors_row:pRow,new_investors_row:gRow,criteria_row:cr,new_criteria_row:cNew,followups_stopped:stopped,queued_dropped:dropped,skipped:skipped,touched:touched}}}];
